head.script:

        var parentObj = opener || parent;
		var popId = WebSquare.net.getParameter( "popupID" );
		var callBackFunc = WebSquare.net.getParameter( "fname" );
		var processGb = WebSquare.net.getParameter( "processGb" );


    	/**************************************************************************
        * function    : init
        * Description : init. 화면 로드시 실행 됨.
        * Parameter   : null
        * Return      : null
        **************************************************************************/
        function init(){

       		gridFocusMode(grdMain, "row");    // 행단위로 셀 선택

			input2.focus();
				if(processGb != "" || processGb.length > 0){
					btnSearch();
				}
        }


    	/**************************************************************************
        * function    : btnSearch
        * Description : 조회
        * Parameter   : null
        * Return      : null
        **************************************************************************/
        function searchBeforeCheck(){
       		/*
           	if (input2.getValue().trim() == "") {
           		showMsg("C_I018", "발행사명");
           		return false;
           	}
           	*/
           	return true;

        }

       /**************************************************************************
        * function    : btnSearch
        * Description : 목록 조회
        * Parameter   : null
        * Return      : null
        **************************************************************************/
        function btnSearch(){

        	if( searchBeforeCheck() == false ){ return; }

        	WebSquare.ModelUtil.removeChildNodes( "BISIssCompPopDTO" );

        	setValue("BISIssCompPopDTO/issueManNm", input2.getValue());
        	setValue("BISIssCompPopDTO/processGb" , processGb);


        	var BISIssCompPopDTO =  {"BISIssCompPopDTO":{}};

        	callProFrame("BIS-KOFIABOND","BISIssCompPopSrchSO","listRnkAnnComp",BISIssCompPopDTO, "BISIssCompPopDTO","respPop");

        }

       /**************************************************************************
        * function    : callBack
        * Description : submission callBack 함수
        * Parameter   : svcId:SO명, fnId:함수명, strResp:결과값 노드명 
        * Return      : null
        **************************************************************************/
        function callBack(svcId,fnId,strResp){
        	//console.log("===> [CmnPopItemCd] callBack() svcId="+svcId+",fnId="+fnId);

			if (svcId == "BISIssCompPopSrchSO") {
				if (fnId == "listRnkAnnComp") {

					grdMain.setXML( getInstanceNode("respPop/root/message/BISIssCompPopListDTO") );
					//grdMainCnt.setValue( "총 건수 : " + grdMain.getRowCount() );

	        	}
 			}
        }

		/**************************************************************************
         * function    : closeWindow()
         * Description : 선택 자료를 return 하고 창 당기
         * Parameter   : null
         * Return      : null
         **************************************************************************/ 
        function closeWindow(row) {

	        //var retXml = WebSquare.xml.indent( grdMain.getRowXML(row) );

	        var retXml = grdMain.getRowXML(row);
	        parentObj.eval(callBackFunc)(retXml, popId);

        }

    	init();
